# Corrected apply_translations.py
translations = {
    7214: """由于五阴相续不断、在生死中往返的因缘，所以被称为“世间”。五阴的本性毕竟空寂，没有执受者，这种寂灭的义理之前已经阐述过了。因为一切法皆是不生不灭的，所以世间与涅槃之间没有任何分别，涅槃与世间之间也没有任何分别。再者：""",
    7221: """“涅槃的实际边界，与世间的实际边界，这两者之间，没有丝毫的差别。”""",
    7228: """究极推求世间、涅槃、实际、无生际，因为在平等性中皆不可得，所以它们之间没有丝毫的差别。再者：""",
    7235: """“佛灭后是有是无等（四见），世间是有边无边等（四见），世间是常无常等（四见），这些诸见分别依止于涅槃、未来世和过去世。”""",
    7242: """关于如来灭后的是否存在有四种见解：如来灭后有、如来灭后无、亦有亦无、非有非无。关于世间是否有边界有四种见解：世间有边、世间无边、亦有边亦无边、非有非无亦无边。关于世间是否常住有四种见解：世间常、世间无常、亦常亦无常、非常非无常。这就是三种共十二种见。如来灭后是否有等四见是依涅槃而起的；世间有边无边等四见是依未来世而起的；世间常无常等四见是依过去世而起的。由于如来灭后的有无等状态皆不可得，涅槃也是如此。正如世间的前际后际、有边无边、常与无常等都不可得，涅槃也是如此。因此说世间与涅槃等没有区别。再者：""",
    7249: """“既然一切法皆空，何处还有有边、无边、亦有边亦无边、非有边非无边？何者为一、为异？何处还有常、无常、亦常亦无常、非常非无常？诸法皆不可得，灭除了一切戏论。既没有受者（人），也没有受处，佛也无所演说。”""",
    7256: """一切法在一切时、以一切种，都是从众缘所生，因毕竟空而无自性。在这样的法中，什么是“有边”，谁是“有边”者？什么是“无边”、“亦有边亦无边”、“非有边非无边”，谁是“非有边非无边”者？什么是“常”，谁是“常”者？什么是“无常”、“亦常亦无常”、“非常非无常”，谁是“非常非无常”者？什么是“身体即是神我”，什么是“身体异于神我”？这六十二种邪见在毕竟空中皆不可得。一切有所得的心皆息灭，一切戏论皆灭除。戏论灭除的缘故，便能通达诸法实相，获得安隐之道。从《观因缘品》以来，分别推求诸法，证明“有”不可得，“无”不可得，“亦有亦无”不可得，“非有非无”亦不可得，这就是诸法实相，也称为如、法性、实际、涅槃。""",
    7263: """因此，如来并没有在何时何处为人演说涅槃的固定相状，所以说一切有所得皆息灭，一切戏论皆灭除。""",
    7270: """中论观十二因缘品第二十六""",
    7277: """问：你以大乘法说明了第一义谛之道，我现在想听你以声闻法来说明如何进入第一义谛之道。""",
    7284: """答：""",
    7291: """“众生被愚痴所覆盖，为后世而发起三种行业。因为造作了这些行业，便随着行业堕入六道轮回。以这些行业为因缘，神识感受六道之身。因为神识有了执著，名色便得以增长。名色增长的缘故，因而产生了六入（六根）。根、尘、识三者和合，便产生了六触。因为有了六触，随即产生三受（苦受、乐受、不苦不乐受）。因为有了三受，便产生了渴爱。因爱而生起四种取着。因取着而有了业有。如果取着者不再取着，就能获得解脱而不再有生。从‘有’而有了‘生’，从‘生’而有了‘老死’。从老死而有了忧愁悲哀等种种苦恼。所有这些事情，都从‘生’而有，只因这些因缘，而集聚成了巨大的苦蕴。这就是所谓的生死，是诸行的根本，由无明所造作，智者是不会去做的。因为这件事灭了，那件事就不再生起，纯粹的苦蕴集聚，就是这样如实地灭尽。”""",
    7298: """凡夫被无明遮蔽了双眼，所以通过身口意业，为后身发起在六道中轮回的诸行。随着所起的行业有上中下之分，神识便进入六道随行受身。以识的执著为因缘，名色得以集聚。名色集聚故有了六入，六入为缘故有了六触，六触为缘故有了三受，三受为缘故生起渴爱，渴爱为缘故有了四取。在四取发生时，通过身口意业造作罪业或福业，使得未来的三有相续不断。从“有”而有“生”，从“生”而有“老死”，从“老死”而产生忧愁悲哀苦恼等种种祸患，这就是大苦蕴的集聚。因此可知凡夫没有智慧，造作了这些生死的根本。智者不会造作，因为如实见到了真理，无明便熄灭。无明灭故诸行也随之熄灭，因灭故果也随之熄灭。如此修习观察十二因缘生灭的智慧，无明灭则诸行灭，乃至生老病死忧悲大苦蕴都如实正灭。所谓的“正灭”就是彻底毕竟的灭尽。""",
    7305: """这十二因缘生灭的含义，在《阿毘昙》和《修多罗》中都有详尽的论述。""",
    7312: """中论观邪见品第二十七""",
    7319: """问：已经听过了用大乘法破除邪见，现在想听听用声闻法如何破除邪见。""",
    7326: """答：""",
    7333: """“我于过去世，是有还是无？‘世间常’等见解，都是依止于过去世而生的。我于未来世，是作（受身）还是不作？‘世间有边’等见解，都是依止于未来世而生的。”""",
    7340: """我在过去世中是有、是无、是亦有亦无、是非有非无？这叫作依止过去世而起的“常”等诸见。我在未来世中是作（受身）、是不作、是亦作亦不作、是非作非不作？这叫作依止未来世而起的“边无边”等诸见。这些邪见是由于什么因缘而被称为邪见的？这件事现在应当说明。""",
    7347: """“过去世有‘我’，这件事是不可得的。过去世中的‘我’，并不会变成今世的‘我’。如果说‘我’就是身体，但身体是有异相（变化）的。如果说‘我’离开了身体，那么哪里还有别处的‘我’呢？离开身体没有‘我’，这件事已经成立。如果说身体就是‘我’，那么实际上并没有一个恒常的‘我’。因为身体不是‘我’，身体的相状是有生有灭的，怎么能把受（五蕴）当作受者（我）呢？如果说离开身体有‘我’，这也是不对的。不通过执受（五蕴）而有‘我’，这在实际上是不可得的。现在的‘我’不离开执受，也不是执受本身，并非没有执受，也不是根本不存在，这就是决定性的结论。”""",
    7354: """说“我”在过去世中存在，这是不对的。为什么呢？先世中的“我”并不直接等同于现在的“我”，否则就会有“常”的过失。如果是常住不变的，就会有无量过失。为什么呢？比如有人因为修福的因缘而先做天人，后来转生为人。如果先世的“我”就是现在的“我”，那么天人就是人。又比如有人因为罪业的因缘而做贱民（旃陀罗），后来转生为婆罗门。如果先世的“我”就是现在的“我”，那么贱民就是婆罗门。譬如舍卫国有一个婆罗门叫提婆达，他到了王舍城还叫提婆达，不会因为到了王舍城就变成了另一个人。如果先做天人后做人，那天人就是人，贱民就是婆罗门。但事实并非如此。为什么呢？天人不等同于人，贱民不等同于婆罗门，因为会有这种种“常”的过失。如果说先世的“我”并不等同于现在的“我”，就像一个人洗衣服时叫“洗衣者”，割草时叫“割草者”，虽然“洗衣者”和“割草者”并非两个不同的人，但“洗衣者”这个身份并不等同于“割草者”这个身份。""",
    7361: """如果说我感受天身时名为天人，感受人身时名为人，我本身没有变而身体有变，这也是不对的。为什么呢？如果“我”是恒常同一的，就不应该说天人变成了人。现在的“洗衣者”对于“割草者”来说，是相同还是不同？如果相同，洗衣者就应该是割草者，这样先世的天人就是人，贱民就是婆罗门，我便有了“常”的过失。如果不同，那么洗衣者就不再是割草者，这样天人也就没有变成人，“我”就变成了无常。无常就意味着没有恒常的“我相”。因此不能说“即是”。""",
    7368: """问：我本身是同一个，只是因为所执受的身心不同而分别是天人还是凡人。执受指的是五蕴之身，因为行业的因缘而分别显现为天人、凡人、贱民或婆罗门，而“我”实际上既非天人也非凡人，既非贱民也非婆罗门。所以没有你所说的那些过失。""",
    7375: """答：这话不对。为什么呢？如果身体变成了天人、凡人、贱民或婆罗门，而这些都不是“我”，那么就意味着离开了身体另外有一个“我”。现在造罪修福、在生死中往返，全都是身体在做，而不是“我”。因为罪业因缘而堕入三恶道，因为福业因缘而生于三善道，如果苦、乐、嗔、喜、忧、怖等全都是身体的感受而不是“我”的，那还要这个“我”做什么呢？就像惩治俗人的罪过，并不涉及出家人一样。五蕴因缘相续，罪福不会丢失，因此才会有解脱。如果一切都是身体的行为而与“我”无关，那还要“我”做什么？""",
    7382: """问：罪业、福业等都依止于“我”，“我”具有认知能力，而身体没有认知能力，所以具备认知的应该是“我”。发起行业的因缘而产生罪福，这是造作之法，应当知道有造作者。造作者就是“我”，身体是“我”所使用的工具，也是“我”所居住的处所。譬如房主用草木、泥土、涂料等修缮房屋，是为了自己的身体，所以随其所用修缮出的房屋有好有坏。我也是如此，随着造作善恶等业而得到好丑不同的身体，六道生死都是我所造作的，所以承载罪福的身体都属于我。譬如房子只属于房主，不属于他人。""",
    7389: """答：这个比喻不对。为什么呢？房主是有形的，有触觉，有力量，所以能修缮房屋。而你所说的“我”，既无形也无触觉，所以没有造作的力量。自己没有造作的力量，也就不能指使他人造作。如果世间有一种法，既无形也无触觉却能有所造作，那还可以信受它作为造作者。但事实并非如此。如果“我”是造作者，那就不应该为自己制造痛苦。如果“我”是忆念者，那应该能贪图享乐的事而永不忘失。如果我不造苦而苦却强行产生，那么其余一切也都是自生的，并非我所造作。如果“见者”是我，那么眼睛能看见颜色，眼睛就应该是“我”。如果眼睛在看而不是“我”在看，那就违背了你先前说的“见者是我”。如果“见者”是我，我既然是眼睛，就不应该能听到声音等其他尘境。为什么呢？因为眼睛是看者，不能听见声音等。因此，“我是见者”这种说法是不对的。如果说就像割草者用镰刀割草，我也通过手等工具能有所造作，这也是不对的。为什么呢？""",
    7396: """现在离开了镰刀另外有割草者，但离开了身心和诸根，并没有另外的造作者。如果说造作者虽然不是眼耳等器官能察觉到的，但也确实存在，那石女的女儿也能有所造作了。这样一来，一切感官功能都应该没有“我”。如果说右眼看到物体而左眼能识别，应当知道另外有见者。这也不对。现在右手习惯了写字，左手却不能，所以并没有另外的造作者。如果另外有造作者，右手所习惯的左手也应该能做，但事实上不能，所以并没有额外的造作者。再者，主张有“我”的人说，看到别人吃果子，自己口中流出口水，这就是有“我”的特征。这也是不对的。为什么呢？这是忆念的力量，不是“我”的力量。而且这正好是破除“我”的依据。人在大众中会因为流口水而感到羞愧，但口水强行流出，自己无法控制，可见并没有一个能主宰的“我”。再者，这还会有颠倒的过失。前世是父亲，今世变成了儿子，如果父子的“我”是同一个，只是身体不同，就像从一个房子搬到另一个房子，父亲依然是父亲，并不会因为进了不同的房子就改变身份。""",
    7403: """如果有“我”，父亲和儿子这两个身份应该是同一个，这样就会有伦常的大过失。如果说没有“我”，而在五蕴相续中也会有这种过失，那也不对。为什么呢？五蕴虽然相续，但有时有用，有时无用。就像葡萄汁，持戒的人可以喝，但变成了葡萄酒就不能喝了，如果再变成苦醋，又可以喝。五蕴相续也是如此，有的阶段有用，有的阶段没用。如果自始至终是同一个“我”，就会有上述过失。五蕴相续没有这种过失。只是因为五蕴和合，才假名为“我”，并没有决定性的实证。就像梁、椽和合才有“舍”，离开梁、椽并没有另外的“舍”。同样，五蕴和合才有“我”，离开五蕴实际上没有另外的“我”。因此，“我”只是一个假名，没有决定性的实体。你先前说离开执受另有执受者，通过执受来分别执受者是天人还是凡人，这都是不对的。应当知道只有执受（五蕴）而没有另外的执受者。如果说离开执受另有“我”，那是行不通的。如果离开执受有“我”，那怎么能说明这个“我”的特征呢？""",
    7410: """如果没有特征可以说，那么离开执受就没有“我”。如果说离开身体没有“我”，身体本身就是“我”，那也不对。为什么呢？身体是有生灭相的，而你所谓的“我”则不应该是这样。再者，怎么能说执受（五蕴）就是执受者（我）呢？如果说离开执受有执受者，这也不对。如果不通过执受五蕴而有执受者，那应该离开五蕴能找到一个执受者。虽然眼等根可以被观察到，但那个执受者实际上并不可得。因此，“我”既不离开执受，也不等同于执受，既非没有执受，也并非根本没有。这就是决定性的结论。因此应当知道，说过去世中存在有“我”，是不对的。为什么呢？""",
    7417: """“过去世中的‘我’没有造作现在的‘我’，这种说法是不对的。过去世中的‘我’与现在的‘我’不同，这种说法也是不对的。如果说现在的‘我’与过去的‘我’是异体，那么脱离了过去的‘我’也应该有现在的‘我’。既然‘我’住在过去世，那么现在的‘我’应该是自生的。如果这样，就会陷入断灭见，丧失了业果报应：变成了那个人造业，而这个人受报，会有这类过失。而且，这还会有‘原本没有而现在突然产生’的过失。这样‘我’就变成了被造作之法，而且是无因产生的。”""",
    7424: """说过去世中的“我”没有造作现在的“我”，这是不对的。为什么呢？因为过去世中的“我”与现在的“我”并不是不同的。如果现在的“我”与过去世的“我”是异体，那就应该离开过去世的那个“我”而产生现在的这个“我”。而且过去世的那个“我”应该还留在过去，此身的“我”则是重新生出来的。如果真是这样，就会堕入断灭见，失掉了一切业果报应。变成了那个人造罪，这个人受报，会有这种种无量的过失。而且，这个“我”应该是先没有而现在突然有的，这也有过失。这样“我”就变成了造作之法，而且是无因产生的。所以，说过去世的“我”没有造作现在的“我”，这是不对的。再者：""",
    7431: """“正如过去世中，关于‘有我’、‘无我’、‘亦有亦无’、‘非有非无’的见解一样，这些都是行不通的。”""",
    7438: """像这样推求过去世中的邪见：是有、是无、是亦有亦无、是非有非无，这些邪见因为之前说过的因缘和过失，都是行不通的。""",
    7445: """“我在未来世中，是作还是不作（受身）？这类见解，都与过去世的情况相同。”""",
    7452: """我在未来世中，是作还是不作受身？这四句见解，正如在过去世中所论证的过咎一样，也应当在这里说明。再者：""",
    7459: """“如果天人就是现在的凡人，那就堕入了常边；天人就不应该出生在人间，因为常法是不生不灭的。”""",
    7466: """如果天人等同于凡人，那就是常。如果天人没有在人间出生，怎么能被称为人呢？常法是不生不灭的。所以“常”是不对的。再者：""",
    7473: """“如果天人不同于凡人，那就是无常。如果天人与凡人是异体，那就没有了相续的关系。”""",
    7480: """如果天人与凡人是异体，那就是无常。无常就会产生断灭等过失，正如先前所说。如果天人与凡人是异体，就没有了相续。如果有相续，就不能说是完全不同的异体。再者：""",
    7487: """“如果一半是天人，一半是凡人，那就堕入了常与无常这两边。这种说法是不对的。”""",
    7494: """如果一个众生的半身是天人，半身是凡人，那么他就同时具有常与无常。天人部分是常，凡人部分是无常。但这显然是不可能的。为什么呢？因为一个身体不能具有两种相互矛盾的特征。再者：""",
    7501: """“如果‘常’与‘无常’这两者都成立，那么才应该成立‘非常非无常’。”""",
    7508: """如果“常”与“无常”都成立，然后才能成立“非常非无常”，因为它是与“常”和“无常”相违背的。现在既然“常”与“无常”都不成立，所以“非常非无常”也就不成立。再者，说现在的生死轮回是无始的，这也不对。为什么呢？""",
    7515: """“如果法确定有所从来，以及确定有所从去，那么生死轮回才是无始的。但事实上并没有这样的事。”""",
    7522: """如果法决定有所从来，或者决定有所从去，那么生死轮回才应该是无始的。但用智慧去推求，并没有法有所从来或有所从去。因此，说生死轮回是无始的，这种见解也是不对的。再者：""",
    7529: """“现在如果连‘常’都不可得，怎么会有‘无常’、‘亦常亦无常’、‘非常非无常’呢？”""",
    7536: """如果这样，用智慧去推求，根本找不到任何可以被称为“常”的法，那么谁又具有“无常”呢？因为是相对于“常”才有“无常”的。如果这两者都没有，又怎么会有“亦常亦无常”呢？如果没有常与无常，怎么会有“非常非无常”？因为是相对于“亦常亦无常”才有了“非常非无常”。因此，依止于过去世的“常”等四句见解是不可得的。而“有边”、“无边”等四句依止于未来世的见解，也是不可得的。现在应当说明，为什么呢？""",
    7543: """“如果世间是有边的，怎么会有后世？如果世间是无边的，又怎么会有后世？”""",
    7550: """如果世间是有尽头的（有边），那就不应该有后世。但现在确实有后世的存在，所以说“世间有边”是不对的。如果世间是没有尽头的（无边），也不应该有后世。但事实上确实有后世，所以说“世间无边”也是不对的。再者，这两边都不可得。为什么呢？""",
    7557: """“五蕴恒常相续，就像灯火的火焰一样。因此，世间不应该是‘有边’或‘无边’的。”""",
    7564: """从旧的五蕴又生出新的五蕴，五蕴就这样次第相续，如同各种因缘和合而产生灯火。如果因缘未尽，灯火就不灭；如果因缘尽了，灯火就熄灭。因此不能说世间是有边 or 无边的。再者：""",
    7571: """“如果先前的五蕴坏灭了，并不以这些五蕴为因，而生起后来的五蕴，那么世间就是有边的。如果先前的五蕴不坏灭，也不以这些五蕴为因，而生起后来的五蕴，那么世间就是无边的。”""",
    7578: """如果先前的五蕴坏灭了，却不以此为因生起后来的五蕴，那么世间就是有边的。如果先前的五蕴灭尽后，不再产生多余的五蕴，这叫作“边”，“边”的意思就是最后一个身体。如果先前的五蕴不坏灭，也不以此为因生起后来的五蕴，那么世间就是无边的，这就是“常”。但事实并非如此，因此“世间无边”这种说法也不对。世间有两种：国土世间和众生世间。这里指的是众生世间。再者，如《四百论》中所说：""",
    7585: """“真实的法、说演法的人以及听受法的人都很难得，因此生死轮回并非‘有边’或‘无边’的。”""",
    7592: """因为没有得到真实法的因缘，所以生死往返没有边际。但有时因为听闻真实法而悟道，所以又不能说是绝对的无边。现在应当进一步破除“亦有边亦无边”。""",
    7599: """“如果世间一半是有边的，一半是无边的，那么这就是‘亦有边亦无边’。这种说法是不对的。”""",
    7606: """如果世间一半有边，一半无边，那么就应该是“亦有边亦无边”。如果是这样，一个法就具有了两种相互矛盾的特征，这是不对的。为什么呢？""",
    7613: """“那个执受五蕴者，怎么可能一分破裂（无常），而另一分不破裂（常）呢？这种事是不可能的。执受本身也是如此，怎么可能一分破裂，而另一分不破裂呢？这种事也是不可能的。”""",
    7620: """执受五蕴的人，怎么可能一部分坏灭而另一部分不坏灭？一个事物不能同时既是常又是无常。执受本身也是一样，怎么可能一部分坏灭而另一部分不坏灭？这会有“常与无常”二相并存的过失。因此说“世间亦有边亦无边”是不对的。现在应当破除“非有边非无边”的见解。""",
    7627: """“如果‘亦有边’与‘亦无边’这两者都能成立，那么‘非有边非无边’才应当成立。”""",
    7634: """因为与“有边”相违背才有“无边”，就像长与短相待而存。与“有”和“无”相违背，才有“亦有亦无”。与“亦有亦无”相违背，才有“非有非无”。如果“亦有边亦无边”确定能成立，那么才应该有“非有边非无边”。为什么呢？因为它们是相待而成的。上面已经破除了第三句“亦有边亦无边”，现在又怎么会有“非有边非无边”呢？因为已经失去了相待的基础。像这样推求，依止于未来世的“有边”等四种见解都是不可得的。再者：""",
    7641: """“由于一切法皆空，世间常等各种见解，会在何处、何时，由谁生起这些见解呢？”""",
    7648: """上面是用声闻法破除诸见，现在用大乘法来说明。诸法从本以来就是毕竟空性的。在这样的空性法中，既没有实体的人，也没有实体的法，不应该生起邪见或正见。“处”指的是处所，“时”指的是日月年岁，谁能被称为“人”？这些就是诸见的本体。如果真有“常”、“无常”等决定的见解，那就应该有一个人产生出这种见解；但既然破除了“我”，就没有人能生起这些见解。虽然处所和色法看似存在但尚且可以破除，何况时间与方位！如果有这些见解，它们应该是决定实有的，既然决定实有就不应该能被破除。然而，通过上面种种因缘已经将其破除，所以应当知道见解没有决定的本体，它们又怎么能产生呢？正如偈言所说：“何处、何时，由谁生起这些见解呢？”""",
    7655: """“瞿昙大圣主，出于怜悯而演说此法，悉数断除了一切邪见。我今稽首顶礼。”""",
    7662: """所谓的“一切见”，简略说有五种见，广说有六十二见。为了断除这些见解，佛陀才演说了妙法。伟大的圣主瞿昙（释迦牟尼佛），拥有无量无边不可思议的智慧，因此我稽首礼敬。""",
}

with open('content/sutras/mulamadhyamakakarika.md', 'r') as f:
    lines = f.readlines()

final_lines = []
i = 0
while i < len(lines):
    line = lines[i]
    if line.startswith("### 原文"):
        header_line_idx = i + 1 # 1-indexed to match translations dict
        final_lines.append(line)
        i += 1
        # Add content of 原文
        while i < len(lines) and not lines[i].startswith("### 现代语译"):
            final_lines.append(lines[i])
            i += 1
        if i < len(lines) and lines[i].startswith("### 现代语译"):
            final_lines.append(lines[i])
            i += 1
            if header_line_idx in translations:
                final_lines.append(translations[header_line_idx] + "\n")
                # Skip all (待翻译) and empty lines until next ###
                while i < len(lines) and ( "(待翻译)" in lines[i] or lines[i].strip() == "" ):
                    i += 1
            else:
                # Not in our target range
                pass
    else:
        final_lines.append(line)
        i += 1

with open('content/sutras/mulamadhyamakakarika.md', 'w') as f:
    f.writelines(final_lines)
